void Solver::rephase() {
    // Reset the rephase counter.
    rephases = 0;

    // Decay the trail‑size threshold more gently (avoid too aggressive shrinking).
    threshold = static_cast<int>(threshold * 0.95);

    // Grow the rephase limit, but slower than the original implementation.
    rephase_limit += 4096;

    // ---- Phase‑saving strategy ----
    // By default keep the best local phase for every variable.
    for (int i = 1; i <= vars; ++i) {
        saved[i] = local_best[i];
    }

    // To diversify the search, invert the phase of a small random subset
    // of variables (e.g., ~5 % of the total). This helps escape local minima
    // without destroying the overall learned polarity information.
    int invert_cnt = vars / 20;               // 5 % of variables
    for (int k = 0; k < invert_cnt; ++k) {
        int v = 1 + rand() % vars;            // pick a random variable
        saved[v] = -saved[v];                 // flip its saved polarity
    }
}

